import re, time
import numpy as np
import mujoco

base = open('model_ref.xml').read()
FULL = mujoco.mjtState.mjSTATE_FULLPHYSICS

def build(attrs='', flags='', vmax=None, remove_plugin=False, remove_equality=False):
    xml = base
    if vmax is not None:
        xml = xml.replace('value="0.05"', f'value="{vmax}"')
    if remove_equality:
        xml = re.sub(r'<equality>.*?</equality>', '', xml, flags=re.S)
    if remove_plugin:
        xml = re.sub(r'<extension>.*?</extension>', '', xml, flags=re.S)
        xml = re.sub(r'<plugin plugin="mujoco\.elasticity\.cable">.*?</plugin>', '', xml, flags=re.S)
    parts = []
    if attrs:
        parts.append(attrs)
    if flags:
        parts.append(f'<flag {flags}/>')
    if parts:
        tag = '<option ' + attrs + '>' + ('<flag ' + flags + '/>' if flags else '') + '</option>' if attrs else '<option><flag ' + flags + '/></option>'
        xml = xml.replace('<compiler autolimits="true"/>', '<compiler autolimits="true"/>\n  ' + tag)
    return mujoco.MjModel.from_xml_string(xml)

def timed(m, seed=123, nstep=600, warm=50):
    d = mujoco.MjData(m)
    d.qpos += np.random.default_rng(seed).normal(0, 0.01, size=d.qpos.shape)
    mujoco.mj_forward(m, d)
    for _ in range(warm):
        mujoco.mj_step(m, d)
    d = mujoco.MjData(m)
    d.qpos += np.random.default_rng(seed).normal(0, 0.01, size=d.qpos.shape)
    mujoco.mj_forward(m, d)
    t = time.perf_counter()
    for _ in range(nstep):
        mujoco.mj_step(m, d)
    dt = time.perf_counter() - t
    st = np.zeros(mujoco.mj_stateSize(m, FULL))
    mujoco.mj_getState(m, d, st, FULL)
    return dt / nstep * 1e6, st

safe_flags = 'contact="disable" actuation="disable" warmstart="disable" filterparent="disable" sensor="disable" midphase="disable" nativeccd="disable" multiccd="disable"'
variants = [
    ('ref', dict()),
    ('contact_off', dict(flags='contact="disable"')),
    ('contact+act', dict(flags='contact="disable" actuation="disable"')),
    ('all_safe_flags', dict(flags=safe_flags)),
    ('all_safe_it1', dict(attrs='iterations="1" ls_iterations="1"', flags=safe_flags)),
    ('vmax1e6_it1', dict(attrs='iterations="1" ls_iterations="1"', flags=safe_flags, vmax='1e6')),
    ('plugin_removed', dict(flags=safe_flags, attrs='iterations="1" ls_iterations="1"', remove_plugin=True)),
    ('equality_removed', dict(flags=safe_flags, attrs='iterations="1" ls_iterations="1"', remove_equality=True)),
]
models = {}
for name, kw in variants:
    try:
        models[name] = build(**kw)
        print(f'built {name}: nv={models[name].nv} disableflags={models[name].opt.disableflags}', flush=True)
    except Exception as e:
        print(f'FAILED build {name}: {e}', flush=True)

ref_states = None
results = {}
# two interleaved rounds to reduce drift
for rnd in range(2):
    for name in list(models):
        us, st = timed(models[name], seed=sum(map(ord, name)) + 17 + rnd)
        results.setdefault(name, []).append(us)
        if name == 'ref' and rnd == 0:
            ref_states = st

for name, vals in results.items():
    us = float(np.mean(vals))
    print(f'{name:22s} {us:9.1f} us/step  rounds={[round(v,1) for v in vals]}', flush=True)
EOF"}

